const attachmentMaxFile=20*1024*1024,attachmentMaxTotal=100*1024*1024;
let attachmentDb,attachmentRecords=[],attachmentReady=false,attachmentError='',attachmentBusy=false;
function openAttachmentDatabase(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('אחסון קבצים אינו זמין בדפדפן הזה'));const request=indexedDB.open('pilot67-attachments',1);request.onupgradeneeded=()=>request.result.createObjectStore('files',{keyPath:'id'});request.onsuccess=()=>{request.result.onversionchange=()=>{request.result.close();attachmentReady=false;attachmentError='יש לרענן את העמוד כדי להמשיך להשתמש בקבצים';mountAttachments()};resolve(request.result)};request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('סגרו לשוניות ישנות ונסו לרענן את העמוד'))})}
function attachmentTransaction(mode,action){return new Promise((resolve,reject)=>{let result;try{const transaction=attachmentDb.transaction('files',mode);const request=action(transaction.objectStore('files'));if(request)request.onsuccess=()=>{result=request.result};transaction.oncomplete=()=>resolve(result);transaction.onabort=()=>reject(transaction.error||new Error('פעולת הקבצים לא הושלמה'));transaction.onerror=()=>reject(transaction.error)}catch(error){reject(error)}})}
function attachmentSize(bytes){return bytes<1024*1024?Math.max(1,Math.round(bytes/1024))+' KB':(bytes/1024/1024).toFixed(1)+' MB'}
function attachmentId(){return crypto.randomUUID()}
function downloadAttachmentBlob(blob,name){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function attachmentRowMarkup(stage,task){const records=attachmentRecords.filter(r=>r.stage===stage&&r.task===task);return `<div class="attachmentToolbar"><button type="button" class="attachButton" data-attach-stage="${stage}" data-attach-task="${task}" ${!attachmentReady||attachmentBusy?'disabled':''}><span aria-hidden="true">＋</span> צירוף קבצים</button><span class="attachmentCount">${attachmentBusy?'שומר קבצים…':!attachmentReady?attachmentError?'האחסון אינו זמין':'טוען קבצים…':records.length?records.length+' קבצים מצורפים':'אפשר לצרף מספר קבצים'}</span></div>${records.length?`<ul class="attachmentList">${records.map(record=>`<li><span class="attachmentIcon" aria-hidden="true">▤</span><div><b title="${esc(record.name)}">${esc(record.name)}</b><small>${attachmentSize(record.blob.size)}</small></div><button type="button" data-attachment-download="${record.id}" aria-label="הורדת ${esc(record.name)}">הורדה ↓</button><button type="button" data-attachment-remove="${record.id}" class="removeAttachment" aria-label="הסרת ${esc(record.name)}">הסרה</button></li>`).join('')}</ul>`:''}`}
function mountAttachments(){if(view!=='journey')return;document.querySelectorAll('#content label.check').forEach(label=>{const checkbox=label.querySelector('[data-task]');if(!checkbox)return;const task=+checkbox.dataset.task,stage=data.stage;let wrapper=label.closest('.taskWithAttachments');if(!wrapper){wrapper=document.createElement('div');wrapper.className='taskWithAttachments';label.before(wrapper);wrapper.append(label);const area=document.createElement('div');area.className='taskAttachments';area.setAttribute('aria-label','קבצים מצורפים למשימה '+(task+1));wrapper.append(area)}wrapper.querySelector('.taskAttachments').innerHTML=attachmentRowMarkup(stage,task)});if(!document.getElementById('attachmentNote')){const note=document.createElement('div');note.id='attachmentNote';note.className='attachmentNote';note.innerHTML=`<div><b>קבצים לכל שלב בדרך</b><p>עד 20 MB לקובץ ו־100 MB בסך הכול. הקבצים נשמרים בדפדפן במכשיר זה, בנפרד מייצוא הנתונים, ואינם מועלים ל־Drive או למרחב הארצי. מחיקת נתוני הדפדפן תמחק גם אותם.</p><span id="attachmentStorageMessage" role="status"></span></div><div class="attachmentBackupActions"><button type="button" id="backupAttachments">↓ גיבוי כל הקבצים</button><button type="button" id="restoreAttachments">↑ שחזור קבצים</button></div>`;const section=document.querySelector('.sectionLabel');if(section)section.after(note)}const message=document.getElementById('attachmentStorageMessage');if(message)message.textContent=attachmentError;}
const renderBeforeAttachments=render;render=function(){renderBeforeAttachments();mountAttachments()};
const attachmentPicker=document.createElement('input');attachmentPicker.type='file';attachmentPicker.multiple=true;attachmentPicker.hidden=true;attachmentPicker.setAttribute('aria-label','בחירת קבצים לצירוף');document.body.append(attachmentPicker);
const attachmentBackupPicker=document.createElement('input');attachmentBackupPicker.type='file';attachmentBackupPicker.accept='application/json,.json';attachmentBackupPicker.hidden=true;attachmentBackupPicker.setAttribute('aria-label','בחירת גיבוי קבצים לשחזור');document.body.append(attachmentBackupPicker);
let attachmentTarget;
async function persistAttachmentRecords(records){if(!attachmentReady)throw new Error('האחסון אינו זמין');const bytes=records.reduce((total,record)=>total+record.blob.size,0)+attachmentRecords.reduce((total,record)=>total+record.blob.size,0);if(bytes>attachmentMaxTotal)throw new Error('חריגה ממגבלת 100 MB. יש להסיר קבצים לפני צירוף נוספים');await attachmentTransaction('readwrite',store=>{for(const record of records)store.put(record)});attachmentRecords.push(...records)}
function attachmentFailure(error){attachmentError=error?.name==='QuotaExceededError'?'אין מספיק מקום בדפדפן. פנו מקום או הסירו קבצים ונסו שוב':error?.message||'שמירת הקבצים נכשלה. נסו שוב';toast(attachmentError);mountAttachments()}
attachmentPicker.onchange=async()=>{const files=Array.from(attachmentPicker.files||[]),target=attachmentTarget;attachmentPicker.value='';if(!files.length||!target)return;attachmentBusy=true;attachmentError='';mountAttachments();try{if(files.some(file=>file.size>attachmentMaxFile))throw new Error('קובץ גדול מ־20 MB. יש לבחור קבצים קטנים יותר');const records=files.map(file=>({id:attachmentId(),stage:target.stage,task:target.task,name:file.name,type:file.type,createdAt:new Date().toISOString(),blob:file}));await persistAttachmentRecords(records);toast(files.length===1?'הקובץ צורף למשימה':'הקבצים צורפו למשימה')}catch(error){attachmentFailure(error)}finally{attachmentBusy=false;mountAttachments()}};
async function backupAttachmentFiles(){if(!attachmentReady||attachmentBusy)return;if(!attachmentRecords.length)return toast('אין קבצים מצורפים לגיבוי');attachmentBusy=true;mountAttachments();try{const files=[];for(const record of attachmentRecords){const bytes=new Uint8Array(await record.blob.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=32768)binary+=String.fromCharCode(...bytes.subarray(offset,offset+32768));const {blob,...meta}=record;files.push({...meta,base64:btoa(binary)})}downloadAttachmentBlob(new Blob([JSON.stringify({format:'pilot67-attachments',version:1,files})],{type:'application/json'}),'pilot67-files-backup-'+new Date().toISOString().slice(0,10)+'.json');toast('גיבוי הקבצים הורד למכשיר')}catch(error){attachmentFailure(error)}finally{attachmentBusy=false;mountAttachments()}}
attachmentBackupPicker.onchange=async()=>{const file=attachmentBackupPicker.files?.[0];attachmentBackupPicker.value='';if(!file)return;attachmentBusy=true;attachmentError='';mountAttachments();try{if(file.size>145*1024*1024)throw new Error('קובץ הגיבוי גדול מדי');const backup=JSON.parse(await file.text());if(backup.format!=='pilot67-attachments'||backup.version!==1||!Array.isArray(backup.files)||backup.files.length>2000)throw new Error('זה אינו גיבוי קבצים תקין של פיילוט 67');const ids=new Set(attachmentRecords.map(record=>record.id));const records=[];for(const item of backup.files){if(!item||typeof item.id!=='string'||!/^[a-zA-Z0-9-]{1,100}$/.test(item.id)||!Number.isInteger(item.stage)||item.stage<0||item.stage>=stages.length||!Number.isInteger(item.task)||item.task<0||item.task>=stages[item.stage].tasks.length||typeof item.name!=='string'||item.name.length>1000||typeof item.base64!=='string'||item.base64.length>Math.ceil(attachmentMaxFile/3)*4)throw new Error('הגיבוי מכיל רשומה לא תקינה');if(ids.has(item.id))continue;const binary=atob(item.base64),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));if(bytes.length>attachmentMaxFile)throw new Error('קובץ בגיבוי גדול מ־20 MB');records.push({id:item.id,stage:item.stage,task:item.task,name:item.name,type:typeof item.type==='string'?item.type:'',createdAt:typeof item.createdAt==='string'?item.createdAt:'',blob:new Blob([bytes],{type:typeof item.type==='string'?item.type:''})});ids.add(item.id)}if(!records.length)return toast('כל הקבצים שבגיבוי כבר קיימים');if(!confirm('להוסיף '+records.length+' קבצים מהגיבוי? קבצים קיימים יישמרו.'))return;await persistAttachmentRecords(records);toast('הקבצים שוחזרו ושויכו למשימות')}catch(error){attachmentFailure(error)}finally{attachmentBusy=false;mountAttachments()}};
document.addEventListener('click',async e=>{const attach=e.target.closest('[data-attach-task]');if(attach&&attachmentReady&&!attachmentBusy){attachmentTarget={stage:+attach.dataset.attachStage,task:+attach.dataset.attachTask};attachmentPicker.click();return}const download=e.target.closest('[data-attachment-download]');if(download){const record=attachmentRecords.find(r=>r.id===download.dataset.attachmentDownload);if(record)downloadAttachmentBlob(record.blob,record.name);return}const remove=e.target.closest('[data-attachment-remove]');if(remove&&!attachmentBusy){const record=attachmentRecords.find(r=>r.id===remove.dataset.attachmentRemove);if(!record||!confirm('להסיר את הקובץ „'+record.name+'” מהמשימה?'))return;try{await attachmentTransaction('readwrite',store=>store.delete(record.id));attachmentRecords=attachmentRecords.filter(r=>r.id!==record.id);mountAttachments();toast('הקובץ הוסר')}catch(error){attachmentFailure(error)}return}if(e.target.closest('#backupAttachments'))await backupAttachmentFiles();if(e.target.closest('#restoreAttachments')&&attachmentReady&&!attachmentBusy)attachmentBackupPicker.click()});
render();
(async()=>{try{attachmentDb=await openAttachmentDatabase();attachmentRecords=await attachmentTransaction('readonly',store=>store.getAll());attachmentReady=true}catch(error){attachmentError='לא ניתן לפתוח אחסון קבצים בדפדפן זה. '+(error?.message||'')}mountAttachments()})();
